{{!-- Styling parameters: class --}}
{{#with this as |ghostcnStyles|}}
{{#if href}}
<a class="ghcn-ui-button{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-variant="{{#match variant "secondary"}}secondary{{else}}{{#match variant "outline"}}outline{{else}}{{#match variant "ghost"}}ghost{{else}}{{#match variant "destructive"}}destructive{{else}}{{#match variant "link"}}link{{else}}default{{/match}}{{/match}}{{/match}}{{/match}}{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}" {{#if ariaLabel}}aria-label="{{ariaLabel}}"{{/if}} {{#if id}}id="{{id}}"{{/if}} {{#if disabled}}role="link" aria-disabled="true" tabindex="-1"{{else}}href="{{href}}" {{#if dataPortal}}data-portal="{{dataPortal}}"{{/if}}{{/if}}>{{#if text}}{{text}}{{else}}Button{{/if}}</a>
{{else}}
<button class="ghcn-ui-button{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-variant="{{#match variant "secondary"}}secondary{{else}}{{#match variant "outline"}}outline{{else}}{{#match variant "ghost"}}ghost{{else}}{{#match variant "destructive"}}destructive{{else}}{{#match variant "link"}}link{{else}}default{{/match}}{{/match}}{{/match}}{{/match}}{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}" {{#if ariaLabel}}aria-label="{{ariaLabel}}"{{/if}} {{#if id}}id="{{id}}"{{/if}} type="{{#match type "submit"}}submit{{else}}{{#match type "reset"}}reset{{else}}button{{/match}}{{/match}}" {{#if disabled}}disabled{{/if}}>{{#if text}}{{text}}{{else}}Button{{/if}}</button>
{{/if}}
{{/with}}

.ghcn-ui-button { box-sizing: border-box; font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); }
.ghcn-ui-button, .ghcn-ui-button * { box-sizing: border-box; }
.ghcn-ui-button:where([data-size="sm"]) { font-size: 14px; }
.ghcn-ui-button:where([data-size="lg"]) { font-size: 18px; }
.ghcn-ui-button:focus-visible, :where(.ghcn-ui-button) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
.ghcn-ui-button { min-height: var(--ghcn-control-height, 40px); padding: var(--ghcn-control-padding, 8px 14px); border-radius: var(--ghcn-control-radius, var(--radius, 8px)); font-size: var(--ghcn-text-small, 14px); line-height: 1.25; display: inline-flex; align-items: center; justify-content: center; gap: var(--ghcn-control-gap, 8px); border: 1px solid transparent; background: var(--primary); color: var(--primary-foreground); font-weight: 600; text-decoration: none; cursor: pointer; }
.ghcn-ui-button:hover { opacity: .9; }
.ghcn-ui-button:where([data-size="sm"]) { min-height: 34px; padding: 5px 11px; font-size: 13px; }
.ghcn-ui-button:where([data-size="lg"]) { min-height: 46px; padding: 10px 17px; font-size: 16px; }
.ghcn-ui-button:where([data-variant="secondary"]) { background: var(--secondary); color: var(--secondary-foreground); }
.ghcn-ui-button:where([data-variant="outline"]) { background: transparent; color: var(--foreground); border-color: var(--border); }
.ghcn-ui-button:where([data-variant="ghost"]), .ghcn-ui-button:where([data-variant="link"]) { background: transparent; color: var(--foreground); }
.ghcn-ui-button:where([data-variant="link"]) { color: var(--primary); text-decoration: underline; }
.ghcn-ui-button:where([data-variant="destructive"]) { background: var(--destructive); color: var(--destructive-foreground); }
.ghcn-ui-button:disabled, .ghcn-ui-button[aria-disabled="true"] { opacity: .5; cursor: not-allowed; }
